new:
Group {
    if CommandLine.arguments.contains("-profilDanseSwiftUI") {
        // Témoin A/B : même dessin, ancien moteur au graphe SwiftUI.
        TimelineView(.animation(minimumInterval: RythmeEcran.pas,
                                paused: dort)) { tl in
            let t = tl.date.timeIntervalSinceReferenceDate
            BoosterStage(still: false, frozenTear: nil,
                         startOpen: false, paused: dort,
                         preferredFramesPerSecond: cadenceBooster)
                .frame(width: 240, height: 300)
                .rotationEffect(.degrees(2.5 * sin(t * 2 * .pi / 7.3)))
                .scaleEffect(1 + 0.025 * sin(t * 2 * .pi / 11.0 + 1.4))
        }
    } else {
        BoosterStage(still: false, frozenTear: nil,
                     startOpen: false, paused: dort,
                     preferredFramesPerSecond: cadenceBooster,
                     danseDouce: true)
            .frame(width: 240, height: 300)
    }
}
